_G.pg.base.ship_skin_words[102330] = {
	hp_warning = "クルシイ……カナシイ……ゼツボウ……",
	feeling3 = "笑顔？わたしが笑ったの？一般的に「嬉しい」とか「楽しい」といったポジティブな感情を表すときに笑顔になるから……なるほど、あなたのそばにいると、ふわふわした気分になるのは「嬉しい」というのね",
