	feeling1 = "ロイヤルのマナーは誰にも適するわけではないようですね",
	skill = "その歪み、正させていただきます！",
	upgrade = "ロイヤルメイドのあるべき姿にまた一歩近づけました。ご主人様に感謝申し上げます",
	propose = "誓いを交わした以上、私から教えるばかりではマナーに反してしまいますね。教えてほしいこと、ですか？はい、心得ております――ご主人様、私に「恋」を教えてくださいませ――",
	feeling5 = "ご主人様といると、姉との日々を思い出させられます。メイドとしての素養と挟持を教えてくれた大切な姉……私は、彼女と同じぐらい優秀なメイドになれたのでしょうか……",
	main = "ロイヤルのマナーには人生の哲学が秘められております。ぜひ覚えて頂きたく存じます|私がメイドの鑑、ですか？……姉のキュラソーをご覧になっていないから、そのような賛辞をいただいたものと存じますが|作法が改善されてきていますね。ですがご主人様、浮かれてはなりませんよ",
	touch = "自信を持って、胸を張って堂々とする立ち振舞いこそが他人の敬意を勝ち取れます",
	voice_key_2 = -1,
	mission_complete = "任務が完了しました。嬉しくとも気品を損なってはなりません。ご主人様",
	battle = "敵にロイヤルメイドの作法をお見せしましょう！",
	id = 202220,
	gift_dislike = "",
	gift_prefer = "礼儀と相手への配慮を併せ持つプレゼント選びですね。感謝申し上げます",
	profile = "シアリーズ級軽巡洋艦、カーリューと申します。C型軽巡洋艦、ですか？恐れ入りますが、その呼び方は精確ではありませんので、お呼びいただく際にはなるべく使わないようお願い申し上げます",
	voice_key = 20222,
	headtouch = "",
	feeling2 = "作法も戦闘も、神は細部に宿ります。ご主人様、いかなる時でもがさつになってはいけません",
	login = "おかえりなさいませご主人様。ネクタイが曲がっております。紳士たる者、外見に乱れがあるわけには参りません。すぐに正させていただきます",
	detail = "いつ、どこにいようと作法とマナーを忘れるわけにはいきません。メイドにとっても艦船にとっても大切なことですから",
	couple_encourage = {}
}


