	feeling3 = "指揮官！感電してないか！？……わ、私は、雷霆の力をうまく制御してお前を助けたいだけなのに、いつも失敗しちゃって……ぐぬぬ……",
	mail = "運命のヒトよ、手紙を整理してやったぞ。……ついでにやっただけだから、別にお礼を言われる筋合いはないから",
	expedition = "委託組が戻ってきた。私の海図があるから、報酬で満載に決まってるでしょ！",
	win_mvp = "この海図こそ、我らの秘密兵器よ！",
	home = "運命のヒトよ、お前が帰ってくる時刻は海流がすでに教えてくれていた！……はいはい、分かった、分かった！お前の予定表をちょっと覗いただけだ…！",
	unlock = "我は木津（きづ）、定めに導かれこの地にて運命のヒトを探しておる…つまり、お前のことだ！くっくっくっ、涙を流して我に感謝し歓待するがよい！……なぜ押し黙っている……や、やっぱり今のは聞かなかったことにしてくれ……",
	touch2 = "きゃぅ！？そんなとこ……だ、だめ……んんっ…////",
	mission = "（ぬ……運命のヒトが任務のことを忘れてる……注意すべきか……お節介だと思われないかな……）",
	vote = "",
	drop_descrip = "川内型軽巡洋艦-木津",
	feeling4 = "くっくっくっ……運命のヒトよ、我とお前をつなぐ「因果の糸」が窺えるぞ。星々の軌跡よりも明るく、避けられぬ雷霆のように疾く――",
	lose = "天の遣いである我の自己鍛錬に過ぎん……",
	feeling1 = "お前のことを見誤ったようね…",
	skill = "雷霆にひれ伏せよ！",
	upgrade = "ついに我の力が完全に顕現した……こ、この程度で怖気付いたりはしないだろうな…？",
	propose = "運命のヒトよ、天が見守る中で久遠の契りを交わそう――夜明けから黄昏へと移ろう日々、人の世が終わるその時まで、永遠にお前と共に在り続けると――",
	feeling5 = "この対となる勾玉は我がいつも携えているもので、運命の伴侶にだけ贈るものだ――だから受け取ってよ！お前のほかに誰がいるというの？……なくしちゃダメだからね！",
	main = "この程度の作業など、大した労力もかからない。……運命のヒトよ、如何に我に助けを求めるべきか……分かっておろう？|運命のヒトよ、我の指先に纏う雷光を見るがいい。これこそが森羅の顕現なり……きゃぅ！？ビリってきた！？くっ…どうして……|風は青萍（せいひょう）の末より吹き上がり、雨も彼岸の空より降り注ぐ……つまりこれから雨になるということだ。運命のヒトよ、備えておくがいい",
	touch = "ぶ……無礼者っ！くっ……///",
	voice_key_2 = -1,
	mission_complete = "運命のヒトよ、任務の「因」がしかと「果」を実らせた……いや、そろそろ任務の状況を確認するよう注意しただけよ",
	battle = "我に続け！航路を拓いてやる！",
	id = 302280,
	gift_dislike = "",
	gift_prefer = "私のために用意したの？ふふん、中々分かってくれるじゃない～",
	profile = "我は木津、天より遣われし摂理の代行者なり――ん？具体的に何の摂理かって？む……雷霆の摂理、気象の法則、ええと……どうだっていいでしょう！",
	voice_key = 30228,
	headtouch = "ひゃぅ！？聖なる角に勝手に触るなんて……んんっ…！",
	feeling2 = "彼方の雷雲が見えるか？天がその猛威を振えば、下界の全ては塵芥に過ぎぬ……なに、心配せずとも良い。この木津がここにいるから",
	login = "秘書艦だと？ふん、お前の世話をするってことか？……それが導きなら従おう……少しだけお前の面倒を見てやる",
	detail = "森羅の意志を解し、雷霆の権能を振るい、万象の因果を窺い知る……これこそが私の力。そしてお前が今必要としているのは……何？1時間後の天気を教えてって……そんなちっぽけなことでいいの？",
	couple_encourage = {}
}


