_G.pg.base.ship_skin_words[302290] = {
	hp_warning = "遊びが過ぎちゃいましたね。てへっ☆",
	feeling3 = "今日はちゃんとそばにいてくれるみたいですね～。いいですよ。じゃあこの後の予定を全部空けてあげますから～",
