	home = "指揮官、ご苦労さま～。私の膝枕で休みます？",
	unlock = "君が指揮官ですね？見た感じ、巻き込まれ体質のようで…まあ、安心して？君を困らせるヒトやコトは、私がその根っこを「処して」あげますよ～",
	touch2 = "指揮官、倍にしてやり返しますよ～",
	mission = "未完了の任務がまだありますよ。私も協力しますから、一緒にテキパキと片付けましょう～",
	vote = "",
	drop_descrip = "川内型軽巡洋艦-名寄",
	feeling4 = "もう、私に他のことへの興味をぜーんぶ失わせちゃって～。だからね、指揮官はずっと面白いままでいてくださいね？でないと……「お仕置き」、しちゃいますから～",
	lose = "もう撤退しなきゃ～。指揮官、一緒に逃げます？",
	feeling1 = "指揮官、あなたと遊ぶのがもうつまらなくなっちゃって……",
	skill = "遊びはもうおしまい。じゃあね～",
	upgrade = "いつになく調子がいいですね～",
	propose = "ようやくこの時がやってきましたか～。私の心はもう君のものですよ。でも君の心は……全部もらいますね～。もちろん、私のやり方で♪",
	feeling5 = "君のそばにいる時間は、今までに味わったことのない楽しさを感じます――だから安心して。これからはしっかり君を掴んで離しませんから～",
	main = "指揮官がぼーっとしている姿って、なんだか無防備な獲物みたいですね。もし今部屋の鍵をかけたら……ふふ♪|指揮官って、いつも色んなルールを守らなきゃいけないみたいですね…私に言わせれば、「万事指揮官の言う通り」ってルールだけあればもう十分だと思います。君もそう思わない？|私、気づきましたよ。そばでちょくちょく喋れば、指揮官は色んな反応を見せてくれるって。うん、これは楽しいですね～",
	touch = "指揮官、そろそろ触り返しますよ？",
	voice_key_2 = -1,
	mission_complete = "任務が完了しました～。指揮官は頑張った私をどう褒めてくれるの～？",
	battle = "一度でキレイに片付けましょう",
	id = 302290,
	gift_dislike = "",
	gift_prefer = "ん？ありがとうございます～。もらっちゃいますね～",
	profile = "晴天に雷電を降らせる名寄（なよろ）です。ん？指揮官ったら、さっきからずっと私の尻尾を見ていますね……触ってみます？頑張って感電しないように守ってあげますから～",
	voice_key = 30229,
	headtouch = "んっ…小動物扱い？ふふふ♪",
	feeling2 = "指揮官、そばに座ってもいいですか？まだ避けないでね――ほら、尻尾があなたと私をぐるっと巻き付けたでしょ？……まあ？また感電しちゃいました？",
	login = "指揮官、手入れを終えたばかりの尻尾を触ってみます？…ん？なんかバチバチするって？また電気が漏れているんですか……",
	detail = "あら、尻尾からまた電気が漏れ出していますわね。でも今回は君のせいかしら――君が来てくれたせいで私、ちょっと興奮しちゃいまして～ふふふ♪",
	couple_encourage = {}
}


