_G.pg.base.ship_skin_words[307170] = {
	hp_warning = "ちっ、この私に対してなんて無礼を…！高くつきますわよ！",
	feeling3 = "こういう料理は味付けが濃すぎてお姉さまは苦手ですわ。……なんですって？数量限定の高級料理でしたの？！じゃ、じゃあ少しだけ食べてあげますけど……（はむはむ）……まあまあですわね……もう一口食べさせて……",
	mail = "新しいメールですって？この雲龍宛の請求書がないかよく見ておきなさいな。まあ最近は結構色々買いましたから…",
	expedition = "さあ、委託組の出迎えに一緒に行きますわよ――と言いたいところですけど、身支度を少し手伝ってもらえないかしら？",
	win_mvp = "これで終わり？私の実力はこんなものじゃありませんわ",
	home = "指揮官、ちゃんと一番高いお菓子を差し入れとして持ってきてくれました？お姉さま相手に適当に誤魔化してはダメですよ？",
	unlock = "ご高名はかねがね承っております。雲龍と申します――ふふ、見惚れていたのかしら？斯様な盛大な前座こそ私にふさわしくてよ？（チリンチリン）さあ指揮官、私との絆の象徴すなわちこの鈴を受け取りなさい？そして私の期待を裏切りませんように",
	touch2 = "え。ちょ、ちょっと…流るる水があなたを許しませんよ……？",
	mission = "まだやることがあるんですって？私の助けが必要だと思ったのでしたら「お願いお姉さま助けてください」と言って―うんうん、その感じで合っていますわ♪",
	vote = "",
	drop_descrip = "雲龍型空母-雲龍",
	feeling4 = "（チリンチリン）はいはいもうお姉さまのことが恋しくなったのですか？……う、うっかり鈴に触れただけって？まあどうせもう来ましたしもう少しだけ指揮官に付き合ってあげますわよ。ありがたく思いなさいっ！",
	lose = "負けたですって？どうやら私の水の力が優しすぎたみたいですね……",
	feeling1 = "鈴の音色が重くなっていますわ……まさかこの私が託す人を間違えたというの？",
	skill = "私の水に抗うんじゃありませんわ！",
	upgrade = "……ふぅ。流るる水、この身を満たさん",
	propose = "絆の証をずっと手元に留めておきたいって？全く欲張りさんの指揮官ですこと、この雲龍お姉さまが相手で本当に良かったですわね♪では……ずっとそばにいることを約束しますわ。天地に流れる水流が全て涸れ果てる、その時まで――",
	feeling5 = "指揮官、今日のお茶、スープ、それとお風呂の香りについて……どう思いました？そんなキョトンとした顔をされても、どれもお姉さまから……お姉さまが用意したものですわよ",
	main = "実は最近骨董品をいくつか買い込みまして、値は張りましたけどまあ私の格にふさわしい品々だったと思いますわ――これから私の部屋まで見に来ませんか？|この辺りにあるものは素材も出自もあまりよろしくない下々のものですし捨てずに残しておくのは……え？お高いですって？で、でしたら多分特別な価値があったりして…？|か、雷？！指揮官はきっと雷が怖いでしょうし、ここはお姉さまが側にいてあげますから、今すぐ私をぎゅーって抱きしめて……じゃなくて私に抱きしめさせて…！",
	touch = "ふーん。気をつけなさいな。この私に気安く触ったら袖が水で濡れてしまいますわよ",
	voice_key_2 = -1,
	mission_complete = "もう任務を全部片付けたですって！？べ、別に私の助けがなくてもなんとかなったじゃないですか……",
	battle = "いざ、共に高波と化さん！",
	id = 307170,
	gift_dislike = "",
	gift_prefer = "これは…！こほん。有り難くもらってあげますわ。指揮官はまあまあ良いセンスをしていますわね",
	profile = "重桜の雲龍型空母の一番艦、水使いの雲龍と申しますわ。こほん。改めまして指揮官、絶美たるこの私の姿をその目にしっかり焼き付けておきなさい",
	voice_key = 30717,
	headtouch = "お姉さま相手にこんなことをするのは失礼ではなくて？んん……でもすごく気持ちよくしてくれていますから大目に見てあげますわ",
	feeling2 = "問題にぶつかったらまずは自分の頭でよく考えて、どうしても分からない時だけ私のところに来なさいな。お姉さまは価値ある問題だけ解決したいですから……こほん。そうです、「価値ある問題」ですわ",
	login = "私に助けを求めたいなら、この前に渡した絆の鈴をツンツン突きなさいな――やっぱりその前に「お願いお姉さま、どうか助けてください～」と言ってちょうだい？",
	detail = "「水化」した私の姿が見たいって？ふふふ、今はダメですけど、どうしても見たいなら、せめて真心込めて桜並木を用意してくださればあるいは――ちょっと！まさか本気にしたんですの！？ねえ！ねえってばー！",
	couple_encourage = {}
}


