	feeling3 = "",
	mail = "",
	expedition = "人間さん、補給が届きましたわ。早く確認してきてください――「船旅に重要な物資よ。慎重に扱いなさい」",
	win_mvp = "段取り良く勝利しましたわね。ふふ、偉いですわ。「もしかして全力を出し切る総力戦でもやりたいの？」",
	home = "おかえりなさい、可愛い人間さん♡「エムデンが安らかな夢を授けてあげる♥」",
	unlock = "いらっしゃい、可愛い人間さん。あなたの行き先を案内する、レセプションのエムデンですわ……貢物さえ捧げてくれれば、人間さんをどこにでも連れて差し上げます♡「ふふふ、たとえこの世に存在しない楽園浄土でも♥」",
	touch2 = "「エムデンにもっとついてきなさい♥」思考を真っ白にして、エムデンが用意した天国を楽しんでいってください♡",
	mission = "",
	vote = "拉票描述",
	drop_descrip = "いらっしゃい、可愛い人間さん。あなたの行き先を案内する、レセプションのエムデンですわ……貢物さえ捧げてくれれば、人間さんをどこにでも連れて差し上げます♡「ふふふ、たとえこの世に存在しない楽園浄土でも♥」",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "可愛い人間さんだけに用意した、愛情のクルージング。エムデンに導かれ、エムデンに全てを預ける喜びを味わっていってください♡「足掻かないで、究極の快楽にその身を沈ませるといいわ♥」",
	main = "可愛い人間さん、迷っているようですね。エムデンのスケジュール表がそんなに気になるのですか？「それとももてなすエムデンのことに夢中になっているの？」|人間さんはこれからの行き先に悩んでいるのですか？エムデンが助けてあげますわ「これこそが人間に授ける褒美よ」|「このクルーズがいつどこに舵を切るのか知りたければ、エムデンに教えを乞いなさい♪エムデンを満足させることができたら少しは手伝ってやらなくはないわ――ふふ♥」",
	touch = "レセプションであっても、ここではエムデンのほうが上ですわ。人間さん「それでも更に一歩先に進みたいというの？」",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 402073,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "ふふ、立場の変化で大胆になったのでしょうか？「それともこれでエムデンの気でも惹くつもり？」",
	feeling2 = "",
	login = "お待たせしました。可愛い人間さん。今日は新世界へと船出したい？「それとも既知の果てでも探りたいのかしら？」",
	detail = "人間さんの体から、好奇心と期待の香りがしますわ――「甘くて美味しい香り、ふふ、嬉しいわ」",
	couple_encourage = {}
}


