	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "可愛い人間さん、あなたはもうエムデンから目を離せませんわ。あなたはエムデンのために、永遠に留まり続ける運命――「エムデンたちの姿に、永遠に夢中になる運命よ♥」",
	main = "光が柔らかくなりましたわ……可愛い人間さん、今ですよ。そのレンズでエムデンに金色の衣を羽織らせてくださいませ|ここはもう少しアングルを低くして――ええ、完全にエムデンを見上げるようにしてくださいませ「エムデンの導きに従えば、完璧な一枚が撮れるわ」|「またぼーっとしているようね」エムデンの姿に見惚れているのですか？それともエムデンを喜ばせる撮り方を考えているのですか？ふふふ、言葉は要りません。その目に答えが出ていますから♡",
	touch = "エムデンのポーズを整えたいのですか？大胆な人間さんですわ♡「エムデンをどんな角度から撮りたいのか……見せてもらうわ♥」",
	voice_key_2 = -1,
	mission_complete = "任務が完了しましたわ。報酬より、エムデンは人間さんが撮った写真の方が気になりますわ",
	battle = "",
	id = 402074,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "「媚を売っているのか、それとも労っているのかしら？」エムデンはどっちでも構いませんよ♪",
	feeling2 = "",
	login = "人間さんは今、どんなエムデンを撮りたいですか？「エムデンたちに相応しい一枚を撮りなさい？」",
	detail = "日差しと水面、そしてエムデンに目が釘付けの人間さん……「全て、疑いようなく完璧だわ」",
	couple_encourage = {}
}


