_G.pg.base.ship_skin_words[402080] = {
	hp_warning = "ぶ、ぶつかっちゃう…！？",
	feeling3 = "どうせ私の攻撃は当たらないし、2倍…3倍撃っても…きっと当たらないし弾薬の無駄だよね…ああ…",
	mail = "エルビングにとっては悪いニュース、指揮官にとってはいいニュースになるように…",
	expedition = "委託組が戻ってきたよ。報酬は……私が取りに行ったらきっと少なくなるよね…",
	win_mvp = "わ、私が一番…？こんなのみんなに遠慮されても…私なんて本当は一番になるような実力がないのに…",
	home = "おかえり…私が指揮官にボロボロになるよう念じたから、指揮官は無事戻ってこられたね…。そう、私の願いなんて絶対に叶わないんだから…",
	unlock = "鉄血所属の巡洋艦、エルビング…どうせ私は戦力にならないから、きっと無視されるのよね…そんなことはないって？そうね…私、使い潰されるぐらいしか価値がないものね…",
	touch2 = "わ、私なんて…///",
	mission = "指揮官、任務の一覧はここよ。ふぅ…",
	vote = "",
	drop_descrip = "ピラウ級軽巡洋艦-エルビング",
	feeling4 = "指揮官がよくしてくれるのは、私がよくやってるからではなく、きっと私のことをかわいそうに思ってるからだよね…？私なんて、指揮官に何もしてあげられないのに…",
	lose = "そうよね、私が戦うぐらいなんだから負け戦に決まっているよね…",
	feeling1 = "きっといい指揮官だと期待しちゃった私のせいだよね……",
	skill = "当たらなくたって…！",
	upgrade = "強化したところで…",
	propose = "誓いの指輪！？そ、そんな私、指揮官と幸せになるようなことは……ああ、きっとこれはエルビングの幸せじゃなくて、指揮官の幸せだから叶ったんだね…よかった…くすん…本当によかった…！",
	feeling5 = "私が願ったことはきっと叶わない…だからよくしてくれる指揮官には――私、不幸になるように願うよ！指揮官とエルビング、一緒に不幸になるようにって……そしたら指揮官はきっと幸せになれるから…！",
	main = "今日は雨かもしれないのね……エルビングが雨だって言えば、きっと晴れるから…|あぅ…艤装が怖い…私こんなに弱いのに、強そうな艤装を持たされても……|エルビングが頑張っても仕事が減らないね…でもエルビングが頑張らなきゃ指揮官の仕事がもっと増える…うぅ…",
	touch = "私にできることは…な、なにもないよね、きっと…",
	voice_key_2 = -1,
	mission_complete = "任務報酬が送られてきたよ。私なんかよりやっぱり指揮官が先に確認したほうが…",
	battle = "乱戦にならないよう気をつけなきゃ…！",
	id = 402080,
	gift_dislike = "",
	gift_prefer = "わ、私に…？本当にいいの…？",
	profile = "鉄血所属、ピラウ級巡洋艦のエルビング…小型巡洋艦に分類された巡洋艦で、本当はカンレキでは全然活躍してなかった…ほら、装甲も薄いし火力も弱いし、取り柄は足の速さと航海時間しか…",
	voice_key = 40208,
	headtouch = "あっ……",
	feeling2 = "私、弱いしドジだし運も最悪だし、指揮官のために役に立てることなんてほとんど無いと思うけど…",
	login = "今日は雨は降っていないの？ああ…私が雨に備えようと傘を持ってきたばかりに……",
	detail = "指揮官？大丈夫？怪我してない？わ、私、指揮官が来る途中大丈夫かなってさっき思わず心配しちゃって………",
	couple_encourage = {}
}


