	mail = "新しいお手紙が届きましたよ。慣例の事務連絡じゃなく、楽しい行事への招待状だといいのですが…指揮官さま、一緒に確認しましょうか？",
	expedition = "委託組の仲間たちが戻ってきました？私も皆を労う準備を終えたところですよ。完璧なタイミングでしょう？",
	win_mvp = "",
	home = "指揮官さま、お戻りですか？ちょうど楽しそうなところを見つけましたけど…よければこれから華甲と一緒に行きませんか？気分転換を兼ねて、ね？",
	unlock = "さあ指揮官さま、見てご覧なさい、これが改修を終えた華甲ですよ。ええと、新しい姿で驚かせてしまいました？ご安心ください。私は変わらず、いつまでもあなたの華甲ですから～……強いて言うなら、楽しいことにはもっと素直になったんじゃないかしら♪",
	touch2 = "え、もしかして私、試されている…？",
	mission = "また楽しい任務でもありました？いつも通り私に手伝わせてください♪",
	vote = "",
	drop_descrip = "さあ指揮官さま、見てご覧なさい、これが改修を終えた華甲ですよ。ええと、新しい姿で驚かせてしまいました？ご安心ください。私は変わらず、いつまでもあなたの華甲ですから～……強いて言うなら、楽しいことにはもっと素直になったんじゃないかしら♪",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "少し変わったとはいえ、指揮官さまはきっと今の華甲も気に入ってくださるでしょう？うふふ。だってどう変わったかはすべて、指揮官さまの「ご指導」のおかげですから♪…ええ、引き続き、責任持って「面倒」を見てくださいませ♪",
	main = "そうだ指揮官さま、茶館を開く機会がありましたら、ぜひ火を使った大道芸をやってみたいです――そのほうが集客にもいいでしょう？…えっ、雰囲気ぶち壊しですか？|礼をもって接し、誠をもって論ずる――華甲の流儀に変わりはありません。話が通じない子がいるとしても、今の私なら大人しく言い聞かせる力も持っていますから♪|激辛火鍋ですか…？あははは…どんどん新しい挑戦をしたくなった私でもさすがにこれは……勘弁してほしいかな……",
	touch = "んー？外に出てサボりたくなっちゃいました？",
	voice_key_2 = -1,
	mission_complete = "あら？任務が完了しました？ふふふ、もしこの後予定が入ってなかったら、よい提案をさせていただいても？",
	battle = "",
	id = 506029,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "あら…もしかして私、最近おとなしすぎました？ふふふ、冗談ですよ",
	feeling2 = "",
	login = "指揮官さま、お仕事が大事なのは分かりますけど、ワクワクドキドキするような楽しいことをして頂戴…？",
	detail = "そういえば最近、パーティーを催すのが楽しいと気づきました。みんなと色々奇想天外なアイデアとか意見を交換できて、中々新鮮な感じです♪",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[519010] = {
	hp_warning = "んー、危うきに近づくことも考えないと…",
	feeling3 = "仲間の皆さんに東煌の蒐集品に興味がある子はいたりしますか？指揮官様さえよければ、ぜひ定安をご紹介いただきたく♪",
	mail = "指揮官様へのお手紙がありますよ。些細な事でも、人知れぬ商いのヒントがあるかもしれませんね",
	expedition = "委託が完了しました。報酬の物資以外にも何かがあるようですね。んーこれはおいくらするものかしら…",
	win_mvp = "この航路はこれでよし、と。新しい販路の開拓もできたりして…？",
	home = "出撃お疲れ様です。いない間に以前仰っていた不足品を少し物色していて…明細はこちらです",
	unlock = "あなたは指揮官様ですね。ご高名はかねがね伺っています。私は東煌所属の定安。今後ともご贔屓に――あ、後ろに積み上げているものですか？ええと……んーつまらない挨拶のお土産…かしら？",
	touch2 = "もう…このままでは定安、指揮官様に助言しなくなりますよ…？",
	mission = "指揮官様、新しい任務がありますよ。これも曰く「原始的な資金の蓄積」なのかしら…？",
	vote = "",
	drop_descrip = "運送艦・定安",
	feeling4 = "先日助けていただいたことへのお返しです。…あ、遠慮なさらないでくださいっ。別にその、何かを企んでいるのではなく、指揮官様にお礼がしたいだけです。すべて普段の執務でお使いいただける小物ですから、どうぞ遠慮なくお受け取りください",
	lose = "んー、これは大損ですね……",
	feeling1 = "日が経てば人の心も知れましょう。指揮官様、どんなに上手に取り繕っていても、いつかはきっとバレてしまいますよ",
	skill = "イチかバチかです！",
	upgrade = "指揮官様の「ご贔屓」、無駄にはしませんよ",
	propose = "ヒトの愛憎は損得勘定できず、まして見返りを期待する投資などではありません。こうしてくださったのはきっと熟考あってのこと……はい、わかりました。指揮官様の気持ちを謹んでお受け致します。定安が一生をかけてお返しさせてくださいね♡",
	feeling5 = "何もかも落ち着いたら、骨董品や書画を扱うお店を開きたいです。うふふ、定安の目利きと指揮官様の人脈があれば不自由なく生活できることでしょう。指揮官様、いかがでしょうか？",
	main = "家計の勘定はきめ細かく、儲けは全力で――母港では「全部欲しい」という子が多いのですか？…それはまあ…ちょっとワガママな子が多いのですね…|執務室の設備を買い替える予定はあります？よかったら定安に任せてもらってもいいですか？いっちばんお安くご用意しますよ|指揮官様、今日の「にゅーす」はもうご覧になりました？うふふ、最新の情勢を追うことで、戦機と商機をうまく掴めるようになるのです",
	touch = "衣装…ですか？んー、確かにスースーしてはいますね…？",
	voice_key_2 = -1,
	mission_complete = "任務報酬が届きましたよ。うふふ、さていかにして商いに生かしましょうか…",
	battle = "支援は任せて安心して戦ってくださいね",
	id = 519010,
	gift_dislike = "",
	gift_prefer = "いい目をお持ちですね。うふふ、ありがたくいただきます",
	profile = "東煌海軍第一艦隊所属の定安と申します。かつては水上機母艦、そして今は輸送艦としてご奉公させていただいております。ほかには……そうだ、逸仙ちゃんはここにいるかしら？今のあの子は昔と大きく変わっているでしょうね。うふふ",
	voice_key = 51901,
	headtouch = "",
	feeling2 = "わあ、指揮官のお部屋には世界中の色んな物が…全部母港の仲間たちから贈られたのですか？うふふ、指揮官様ったら皆に好かれているのですね",
	login = "おかえりなさいませ指揮官様。うふふ、気持ちが落ち着いているうちに大事な決断を先になさってくださいね",
	detail = "母港の売店は明石が独占していて、たまにあくどい商売もされているようですね。もし私にも機会が……今はそういう決まりがあるから難しい、ですか？しゅん……",
	couple_encourage = {
