	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "指揮官様、ここでの下見が終わったら次はどこに――アトラクションを全部見て回るのですか？……確かに、今度この水着を着て指揮官様と遊びますから、予行練習にちょうどいいですけど……あぅ…い、いいえ、頑張りますっ！///",
	main = "ご安心ください、指揮官様。この時間なら皆が寝ていますし、見回りの子も流石にここには気づきません……よね？あぅ…っ！|（これはあくまで指揮官様とのマーケティング…そう！商売のために必要ですから！突然何かに目覚めたり快感を覚えたりはしない…はず！うぅ…！///）|し、指揮官様？寒いようでしたらこのコートに入ります？私もその…はくちゅん！",
	touch = "も、もう一枚撮ったほうがいいですか…？",
	voice_key_2 = -1,
	mission_complete = "任務完了です！今度の投資先はどこにしましょう…？",
	battle = "うぅ…気をつけなきゃ…！",
	id = 519012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "",
	feeling2 = "",
	login = "ハァ、ハァ……そんなに長い距離じゃないのに、なんだか歩いただけで疲れちゃいました…やっぱりバレないように気を使ったせいですよね…？",
	detail = "はぁ…購買部の新品の水着に勝つには、デザインとコストにこだわる以外にも、実際に着用される場面を予め体験しておくことでみんなのニーズに応えられるようにする……はぁ……そ、そうですよね？指揮官様…？",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[520000] = {
	hp_warning = "指挥官，集中精神、加倍小心！",
	feeling3 = "即使有一天不再需要我去战斗，我也想永远守望着渤海，永远眺望着被晚霞染红的海面……",
	mail = "指挥官，有新的信件，需要我代为拆阅吗？",
	expedition = "太好了，全员安全回港！",
	win_mvp = "能帮到指挥官真是太好了！",
	home = "稍微休息一下吧，精神一直紧绷着可不好",
	unlock = "驱逐舰“鞍山”号报到。妹妹们与指挥官就由我来守护！",
	touch2 = "喂——妹妹们可能会看到啊",
	mission = "为了守护和平，完成这些任务也是必要的",
	vote = "",
	drop_descrip = "鞍山级驱逐舰1号舰—鞍山，舷号101",
	feeling4 = "指挥官，请放心，无论你前往哪里，我都会跟在你身边守护你。嗯？那当然是因为你是我的……",
	lose = "整军再战，我们决不能就此退缩！",
	feeling1 = "指挥官，我在渤海湾养的山楂到花期了，可以回去看看吗？",
	skill = "吾德天助，前后遮罗",
	upgrade = "这样对付“狄海文”之流就更加得心应手了",
	propose = "指挥官，我的生命、我的躯体、我的灵魂，从今以后都将归属于你。你可要，好好地承担起这份责任哦",
	feeling5 = "能遇到指挥官真是太好了，结识了各种各样的朋友，产生了多姿多彩的回忆……呐，指挥官，等我卸下“四大金刚”的职责后，一起去环游世界吧！",
	main = "哇，我还是第一次见到战列舰|抚顺跑哪去了？多少听听姐姐的话啊…|抚顺、长春、太原，不管哪个都是令我骄傲的妹妹！",
	touch = "指挥官……嘻嘻，偶尔这样也不错呢",
	voice_key_2 = -1,
	mission_complete = "再接再厉，还不能松懈！",
	battle = "你们是为了什么而战斗呢？",
	id = 520000,
	gift_dislike = "",
	gift_prefer = "",
	profile = "东煌鞍山级驱逐舰首舰“鞍山”号，东煌第一代“四大金刚”之首。作为长姐（旗舰），参加过诸多演习、监视和对峙，并都取得了足以自豪的成绩。虽然没有经历过实战，但我可是世界上行驶里程最远的驱逐舰之一哦",
	voice_key = 52000,
	headtouch = "",
	feeling2 = "指挥官，为了守护重要的事物，战斗是必要的。这可不是个人喜好问题",
	login = "今天的事项表也很满，一起加油吧！",
	detail = "指挥官，你想知道些什么呢？",
	couple_encourage = {
		{
			{
				50102
			},
			1,
			"不要乱跑，来姐姐这边",
			0
		},
		{
			{
				50103
			},
			1,
			"记住，在战场上再谨慎也不为过！",
			0
		},
		{
			{
				50104
			},
			1,
			"再勇敢一点！对！就是这样！",
			0
		}
	}
}


