_G.pg.base.ship_skin_words[900267] = {
	hp_warning = "あははははは！これこそが私の戦場だ！",
	feeling3 = "同志よ、勘違いしないでほしい。この戦いは私たちだけの戦いではなく、あなたの戦いでもあるぞ。現状に満足せず、ともに励んでいこうではないか",
	mail = "手紙だ。同志よ、早く開封しようじゃないか",
