_G.pg.base.ship_skin_words[900269] = {
	hp_warning = "",
	feeling3 = "妬み？いいえ、そんなことはありません。エンタープライズ先輩は私達全員に尊敬される英雄です。ただ、彼女の七光だとされていることは、私にはやっぱり……",
	mail = "新しいメールです。どうぞ",
	expedition = "私たちエセックス級の誕生は、強い兵站部署があってのことです。ちゃんとみんなに感謝しないと",
	win_mvp = "エンタープライズ先輩、私の活躍を見ましたか！",
	home = "出撃艦隊…無事母港に帰投しました。指揮官、戦闘報告の下準備は完了済みです。時間が惜しいので、今からその振り返りをしましょう",
	unlock = "ここがエンタープライズ先輩の…こ、コホン！ユニオンの最新鋭空母・エセックス、正式に着任しました。指揮官、私の活躍を期待していてください！みんなの期待を絶対に裏切ったりはしません！",
	touch2 = "こ、こんなこと！私、私……",
	mission = "まだ新しい任務が……私にも任せてみませんか？",
	vote = "",
	drop_descrip = "エセックス級航空母艦・エセックス（CV-9)",
	feeling4 = "私エセックスは誰にも負けません。たとえ相手がエンタープライズ先輩だとしても、です。……しかし、どうやってみんなにそれ認めてもらえるか――指揮官、あなたならきっと分かっていますよね？",
	lose = "このままでは終わらない……絶対に！",
	feeling1 = "エンタープライズ先輩、こんな指揮官に我慢して従っているのか……",
	skill = "大空を翔けよ！",
	upgrade = "ジェット機はいつになったら……",
	propose = "お互いが支え合っている幸せな気持ちは、一度でも感じたら虜にされますね。指揮官、ありがとうございます。エセックスがどうやってみんなに認めてもらえるか、一人で悩む必要はなくなりました――エセックス、これからはずっとあなたのそばで、あなたと共に歩むことを誓います",
	feeling5 = "エンタープライズ先輩のようなヒーローになれないかもしれません。ですが、彼女と同じく人々の記憶に残る存在になれるような気がします。……だって指揮官となら私、どんなことでもできる気がしますから…",
	main = "みんなエセックス級は強いと認めていても、いざ口にするとやはりエンタープライズ先輩ばっかり…はあ……|私には同型艦がたくさんいますね。ネームシップとして頑張って手本を見せてあげないと……|武蔵と大和ですか？彼女たちは…うん、尊敬すべき素晴らしいライバルです。いつかまた出会えたらいいですね",
	touch = "！出撃ですか？私に任せてください！――はあ、雑談したかっただけですか……",
	voice_key_2 = -1,
	mission_complete = "任務報酬が届きました。受け取りに行かなくてもいいですか？",
	battle = "航空隊直掩配置に到達、防空態勢移行完了――全艦、最大戦速！",
	id = 900269,
	gift_dislike = "",
	gift_prefer = "",
	profile = "エセックス級のネームシップエセックスです。建造されてから多くの期待を寄せられていましたが、やはり私よりエンタープライズ先輩の活躍の方がもっと注目されていましたね。……私だってもっと早く戦闘に参加していたら……",
	voice_key = 10709,
	headtouch = "",
	feeling2 = "大艦巨砲主義の時代の終焉をこの目で見届けました。航空母艦の時代も、いつか終わりを迎えるのでしょうか……",
	login = "やっと来ましたか。…全ては準備万端です。指揮官、出撃の指示を！",
	detail = "指揮官は何を知りたいですか？私が知っていることならなんでもお答えしますが――",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[900270] = {
	hp_warning = "しまった、思ったより敵が多い……",
	feeling3 = "あ、指揮官！これ――いったー！誰よここに台車を置いたのは！もうなんで私はいつもこんな目に……あ、いや、なんでもない！それより指揮官、私の出番は？",
	mail = "新しいメール…作戦任務の指示かな？",
	expedition = "軍事委託完了、補給受領も完了～へへ、さすが指揮官、戦力は兵站あってこそってよく分かってる！",
	win_mvp = "勝利の栄冠は、恐れなきイントレピッドの手にあり！",
	home = "ふぅ～戻った！あ、修理補給戦闘報告戦術振り返りブリーフィング、5分で片付けられる？次の出撃にpush ahead（プッシュアヘッド）！",
	unlock = "エセックス級の「The Fighting “I”（ファイティング・アイ）」、イントレピッド参上！指揮官、戦闘任務があれば任せてくれ！勝利と栄光を君に！",
	touch2 = "っ……はあ、褒めるどころかぶっ飛ばされる行動だよ、これ",
	mission = "任務って難しいの？どうしてもこなせなら試しに私にも任せてみる？",
	vote = "",
	drop_descrip = "エセックス級空母「イントレピッド」（CV-11）",
	feeling4 = "暇なときは本を読んだり、映画を見たり、星を眺めたりするのが好きよ。――あ、そういえばカサブランカから映画のチケットもらったけど、見に行かない？",
	lose = "またもや修理ドック行き…（小声）なんでいつも私が…な、なんでもない！",
	feeling1 = "指揮官、今の君の行動は卑怯者のそれよ！",
	skill = "イントレピッド、Getting on!",
	upgrade = "強化できるとこ、いくらでもあるよ！ジェット機1ダースとか？",
	propose = "まさか指揮官が先に手を出してくるとは思わなかったね…もう、しょうがない。指揮官、これからもよろしく！私がそばにいるから、君は何も恐れず望む未来に突き進め！",
	feeling5 = "夜空の星々は遠い。恐れずに勇気を持って挑むにしろ、手が届くには途轍もない時間も努力も必要よ――それはそれとして、そばにいる指揮官なら今すぐ捕まえられる。つまりこういうこと……へへ、そうだろ？",
	main = "指揮官は星々を眺めるのが好き？あはは、天体観測とかガチの趣味じゃなくてもいいよ。興味があったらちょっと話そう？|潜水艦か…まあ強いよ。私ならちょっと対応できるかもしれないよ|エセックス級は数こそ多いもののみんな特徴がある…え、艦としての性能の特徴以外は？あんまり考えたことがなくて、ちょっと悩ましいな…",
	touch = "なんか飲みたいものないかって？んじゃあ――「マティーニを、ステアせずシェイクして」――Just kidding！",
	voice_key_2 = -1,
	mission_complete = "Mission accomplished！ほら、やリさえすればできないことなんてないじゃない！",
	battle = "発艦準備問題なし――攻撃隊、かっ飛べ！Roll out！",
	id = 900270,
	gift_dislike = "",
	gift_prefer = "",
	profile = "私はエセックス級3番艦、イントレピッド！あの大戦ではちょっと不運が重なって、変なあだ名をたくさんつけられちゃったけど……ふふん、重要なのは今！指揮官のもとで、全力で戦ってみせる！",
	voice_key = 10711,
	headtouch = "うお！？髪の毛が！？",
	feeling2 = "何も恐れない大いなる勇気、それが私、イントレピッド！覚えてくれよ！",
	login = "今日の出撃メンバーに私の名前は入っているか？ないなら付け加えてくれ！",
	detail = "相手が誰であろうと挑んでみせる――というのは当然だけど、正直色々あって思いっきり戦えなかったな…",
	couple_encourage = {
		{
			{
				10717,
				10722
			},
			1,
			"TaskForce38、Let's Rock！",
			0
		}
	}
}


_G.pg.base.ship_skin_words[900271] = {
	hp_warning = "このタイミングで……！",
	feeling3 = "…沈黙は苛立ちを意味しているわけではない。考え込んでいる、もしくは考え込んだことをどうやって言い出すか、考え込んでしまっているだけだ",
	mail = "メール…新しい情報はあるか？",
	expedition = "すまん、委託から戻ってきた子たちを出迎えてくる。お前はここで結果を待っていればいい",
	win_mvp = "お前たちが選んだ結末はこれか",
	home = "戻ったか。……では、次の出撃の準備に入るか？",
	unlock = "エセックス級の一人、このバンカー・ヒルが艦隊に加わり、お前の指揮下に入った。案ずるな、じきにお前も私の実力を目にすることになるだろう",
	touch2 = "どうやら指揮官には記憶に残る「体験」が必要のようだな",
	mission = "任務…早くこなしたほうがいい",
	vote = "",
	drop_descrip = "エセックス級航空母艦・バンカー・ヒル（CV-17)",
	feeling4 = "最近、思考が妙によく阻害される気がする。考え込むと、ついつい誰かの顔が思い浮かび、冷静ではいられなくなる……",
	lose = "その力……「竜の顎（ドラゴンジョーズ）」をも凌ぐ強敵だというのか…！",
	feeling1 = "今は話したくない",
	skill = "足掻くな！",
	upgrade = "また…強くなったか",
	propose = "すまない…頭の中が真っ白だ。くっ、一体なにを言えば……そうだ！「お前への忠誠と愛は永遠に続くだろう」――これでいいか？",
	feeling5 = "戦いのために生まれた私たちは、戦闘以外に存在価値などないと思った。お前との日々を過ごして、私たちには戦うこと以外にも生きる価値がある――そんな…気がする",
	main = "今日もどこかでは、戦争の炎に巻き込まれているのだな|エルドリッジの能力？あまりよくわからないが……どこかで見たような……|エセックス級攻撃空母編隊の前で、抵抗など無意味だ",
	touch = "……沈黙は苛立ちを意味しているわけではない。用事があれば声をかけてくれ",
	voice_key_2 = -1,
	mission_complete = "報酬が多い？当然だ",
	battle = "なぜ敵になるのを選んだか……！",
	id = 900271,
	gift_dislike = "",
	gift_prefer = "",
	profile = "エセックス級のバンカー・ヒルだ。名はかの独立戦争の戦場から来ている。活躍した戦闘は多いが…悲しみと痛みをもたらす戦争のことだ。多くは語るまい",
	voice_key = 10717,
	headtouch = "",
	feeling2 = "人間の戦争に美しさなど存在しない。傷つけ合い、殺し合いなど醜いものしか存在しないのだ",
	login = "今は非常時だ。休日でも「ホリデーエクスプレス」の覚悟をしてくれたまえ",
	detail = "指揮官、なぜこちらを見つめている……？",
	couple_encourage = {
