_G.pg.base.ship_skin_words[900350] = {
	hp_warning = "",
	feeling3 = "指揮官、私の意見を尊重するのは良いのですが、くれぐれも自分の考えをしっかりお持ちください。そもそも、指揮官に賛同しなければ、こうもお側に立っていられませんもの、うふふ",
	mail = "指揮官、情報の即時対応は大切です",
	expedition = "何ぼーっとしているんですか？委託、完了しましたよ",
	win_mvp = "そんなものかしら",
	home = "本に全てが載っているわけではありません。実戦でのみ得られるものもあります。指揮官はどうかしら？",
	unlock = "戦場は一瞬にして変わります。冷静に考え、慎重に動くことこそ負けない戦ができます。指揮官はいかがかしら？二水戦神通、ご挨拶申し上げます",
	touch2 = "指揮官は思っていたより大胆なようで…心の準備もできているということかしら？ねぇ？",
	mission = "新しい任務の要綱を取りまとめました。ご確認を",
	vote = "",
	drop_descrip = "川内型軽巡洋艦二番艦・神通",
	feeling4 = "かの有能な将軍たちはなぜ臣下の位に甘んじているか、ご存知ですか？自分の限界？それとも主君への傾倒？私は…どちらもある、と思いますよ",
	lose = "全艦転進。無駄な犠牲は出しません",
	feeling1 = "艦隊のことはもう私におまかせください",
	skill = "この時を待っていました…！",
	upgrade = "もっと深い海域への進軍も検討可能かしら？",
	propose = "計略定まって兵動く、最善の時に最高の選択をするのが私の信条です。はい、今は自信を持って話せます。最高の指揮官を、私が選びました",
	feeling5 = "人の評価に左右されることなく、自分を貫くのはリーダーたる者が持つべき気質です。征く道は正しいかどうか…付いてくれる人たちを見ればわかります。たとえば、私……",
	main = "慎重は軟弱というのなら、勇猛さは無謀だというべきかしら？|真理などありません。比較し、実践し、失敗してこそ正しい選択ができるのです|他人に理解されなくても、正しいことをするつもりです。ええ、たとえ指揮官に理解されなくても…",
	touch = "うん？ご用かしら？今、艦隊運営のことについて考えているところです",
	voice_key_2 = -1,
	mission_complete = "任務報酬が届きました。……うん？いいえ、どうやって最大限に利用できるか考えているだけです",
	battle = "全艦、突撃せよ！",
	id = 900350,
	gift_dislike = "",
	gift_prefer = "",
	profile = "川内型二番艦、二水戦旗艦・神通と申します。かつては軟弱と評されましたが、コロンバンガラ島沖海戦で自らを証明してみせました。二水戦の輝き、ここでもう一度お見せしましょう。",
	voice_key = 30213,
	headtouch = "",
	feeling2 = "旗艦を務めたことがあっても、今はただの兵士です。ほかの子と同じ扱いにしていただいて結構です",
	login = "指揮官、外で油を売るのは良いですが、執務室では執務に集中するようお願いします",
	detail = "次の作戦と資源配分……あら、指揮官ではありませんか。どうぞお好きに",
	couple_encourage = {}
