_G.pg.base.ship_skin_words[900351] = {
	hp_warning = "逆転策は思いついてるわよ！",
	feeling3 = "おっ、お喋りに付き合ってくれるようになったわね。じゃあ話題は何にする？小難しい艤装とか技術の話？それとも普段の生活とか？…あたしに選ばせちゃう？",
	mail = "新着メールがあるわよ。ふふ、やっぱり楽しみにしてたんだ～",
