_G.pg.base.ship_skin_words[1101010] = {
	hp_warning = "大丈夫、これぐらいなら自分で治せますから",
	feeling3 = "……この苔は予想以上の早さで生長していますね。ほら、胞子嚢が対照群より37%速く…ん？どうしてそんな目で見てるのですか？私が一気に喋りすぎました？…エヴァーツェンの笑顔が見たいだけ、ですか…？",
	mail = "メールが来ています。忘れずにご確認を",
	expedition = "委託組が戻ってきました。今回の目的地は…研究し甲斐がありそうです。指揮官、今度私にも行かせてください",
	win_mvp = "勝ちましたね。良かったです",
	home = "戻ってきて早々もうお仕事です？……魔法で疲れを解消してあげますから、ここに座ってください",
	unlock = "ん。あなたが指揮官ですか？私はエヴァーツェン。……待って。この記録を終わらせてからまた詳しく話しましょう",
	touch2 = "……？！やめてください…恥ずかしいですから…",
	mission = "指揮官、任務を忘れずにこなすように。…先に魔法で疲れを取っておきましょうか？",
	vote = "",
	drop_descrip = "アドミラーレン級駆逐艦-エヴァーツェン",
	feeling4 = "指揮官、部屋の植物に触らないでください。実験用のため、微量ですが毒を持つものもあって……ああ、ありました。私が作ったキキョウのしおりを差し上げます……裏にキキョウの花言葉も添えてありますので",
	lose = "けが人はいますか？治療を手伝いますよ",
	feeling1 = "指揮官、静かに。苔類の観察の邪魔です",
	skill = "甦って",
	upgrade = "魔力が、上がっています……",
	propose = "…指揮官、このジプソフィラをあなたに。魔法で一番美しい状態のままにしますから枯れる心配はありません……ええ、あなたへの愛のように、枯れることも消えることもなく、永遠にこのままですよ",
	feeling5 = "指揮官の隣に座って最近の観察データを整理してもいいですか？……ありがとう……え？距離が近すぎて気になりますか？でも日向ぼっこできるのはここしかありませんし…「気になる」程度でしかないなら、このままでも問題ないですね",
	main = "指揮官、植物ばかり見ていないで業務に集中してください。…ん？理解しやすいように「植物」という呼び方で一括りにしましたけど、気になるようでしたら逐一説明して差し上げ…もちろん、お仕事を終えてから、ですよ|松のミニ盆栽が前より元気になった、ですか？はい、魔法をかけましたので。それと、正しい育て方を書いたふせんを植木鉢に貼っておきました|マイクロスコープ越しで見てみますか？この葉状体の色合いは通常より濃くて、クロロフィル含量も明らかに増えています…自然って不思議ですね",
	touch = "ちょうどいいところに。今日の成長実験には助手が必要なので、手伝っていただけますでしょうか？",
	voice_key_2 = -1,
	mission_complete = "任務、すべて完了しました。お疲れ様です。よくできましたね",
	battle = "準備ができたら行きましょう",
	id = 1101010,
	gift_dislike = "",
	gift_prefer = "嬉しいです。お気遣いありがとうございます",
	profile = "チュリッパ王国所属、アドミラーレン級駆逐艦のエヴァーツェンです。母港の自然生態系について観察研究中です。興味がおありでしたら一緒にどうでしょう？静かにね",
	voice_key = 110101,
	headtouch = "治癒魔法の一種ですか？",
	feeling2 = "これは私が作った小型の熱帯雨林の生態系です。興味がおありでしたら、一緒に観察記録を取りませんか？",
	login = "緑の多い環境では作業効率が上がりますから、エアプラントとカクタスの植木鉢をいくつか足しておきました。どれも面倒が見やすくて……見てないでお仕事に集中してください",
	detail = "静かにしてください。シャマキマダラルリツバメの産卵を観察していますので",
	couple_encourage = {
		{
			{
				110201
			},
			1,
			"パロットチューリップがなんだか元気ないみたいで…見ていただけますか？",
			0
		}
	}
}


_G.pg.base.ship_skin_words[1101011] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "このデータには何箇所か異常がありますね、もう一度対照実験を…あ、指揮官。今水を持ってきます――実験、ですか？急ぎではありませんので、後でやればいいです",
	unlock = "指揮官、適当にくつろいでください。……どうしてそんなに離れるんですか？それでは日向ぼっこができなくなりますよ",
	touch2 = "…窓際だと…恥ずかしい、ですけど………///",
	mission = "",
	vote = "",
	drop_descrip = "指揮官、適当にくつろいでください。……どうしてそんなに離れるんですか？それでは日向ぼっこができなくなりますよ",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "こういうのは初めてですね。…何もせず、ただ好きな人と静かに日向ぼっこをして――とても居心地がいいです。そんなに困惑した顔をしないでください。私が好きな人は指揮官、あなたですよ",
	main = "何をじっと見つめているのですか？…オオカバマダラの渡りに発生した規則性偏差に興味があるのですか？……なら詳しく説明しましょうか？|これは観賞用の植物で、毒もないし人に害はありませんから、近くで見ても……うん、観測スポットを開けておきました|休日の私の様子にまだ慣れないのですか？私だって息抜きは必要ですし…あなたもそうです。もう少し肩の力を抜いたらどうでしょう？",
	touch = "私と同じように着替えませんか？少しは楽になりますよ",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 1101011,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "…ん？私の隣がいいんですか？",
	feeling2 = "",
	login = "一緒に窓辺に座りましょう。…あ、足元に気をつけてください。私のノートがありますので",
	detail = "今日は静かにする必要がありませんから……その、お喋りでもしませんか？あなたのこと、もっと知りたくて…",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[1101012] = {
	hp_warning = "",
	feeling3 = "",
	mail = "",
	expedition = "",
	win_mvp = "",
	home = "水のサンプルを採っています。気になるのでしたら……こっちに来て。やり方を教えてあげますから",
	unlock = "指揮官、コサギたちが降りた場所が見えますか？あの辺りはみんなで一緒に植えたマングローブ林で、鳥たちのおうちになっているんです",
	touch2 = "……小動物たちが見ていますよ……///",
	mission = "",
	vote = "",
	drop_descrip = "指揮官、コサギたちが降りた場所が見えますか？あの辺りはみんなで一緒に植えたマングローブ林で、鳥たちのおうちになっているんです",
	feeling4 = "",
	lose = "",
	feeling1 = "",
	skill = "",
	upgrade = "",
	propose = "",
	feeling5 = "マングローブの根系は特別で、お互いの根が絡み合い、支え合って離れません……。私たちも同じく、支え合って一つになりたいです",
	main = "……マングローブの森の守護精霊みたいって？じゃあ指揮官、一緒にこの場所を守っていきませんか…？|マングローブの根が前回来た時より広がっていますね。近くで見てみませんか？細かく説明してあげますよ|暑いですか？じゃあ…こっちに来て、一緒に足を海に浸しましょう。そしてこのまま、風の心地よさに身を預けて……どうですか？気持ちいいでしょう？",
	touch = "どうかしましたか？しっかり座れなくて不安定でしたら……私の手を握っていてください",
	voice_key_2 = -1,
	mission_complete = "",
	battle = "",
	id = 1101012,
	gift_dislike = "",
	gift_prefer = "",
	profile = "",
	voice_key = 0,
	headtouch = "隣に来て休んでください。……とても涼しい、から……",
	feeling2 = "",
	login = "私と一緒に深呼吸しましょう。すーはー……マングローブ林の新鮮な空気が、気分を軽やかにしてくれますよ",
	detail = "治療魔法がフォローできる範囲には限界があります。でもこのマングローブ林なら、海の生き物や渡り鳥たちに生息地を提供するだけでなく、生態系も守ってくれる……魔法よりもずっと凄まじいです",
	couple_encourage = {}
}


_G.pg.base.ship_skin_words[1102010] = {
	hp_warning = "くっ、みんなは大丈夫でしょうか…",
	feeling3 = "「Klein Witje（クライン・ウェチェ）」…白ちゃんはエヴァーツェンにあげる予定です。あの子は小さな花が好きですから……指揮官さんもお好きなんですか？じゃあ後で指揮官さんの分も用意しますね～",
	mail = "指揮官さん、新しいメールが…読み上げて欲しい、ですか？ええと、こうしたら画面を開けますよね…あ、あれ？メールが消えちゃいました…？",
	expedition = "指揮官さん、委託に出かけた子たちが戻ってきましたから、早く出迎えに行ってあげてくださいね。きっとみんな指揮官さんに会いたがっていますよ",
	win_mvp = "勝ててよかったぁ…みんなのおかげですよ♪",
	home = "指揮官さん、おかえりなさい、あのぉ……コーヒーマシンを見ていただけませんでしょうか…？マニュアル通りにやってみましたけど、抽出ボタンを押すと途端に煙が出て……",
