_G.pg.base.ship_skin_words[9702050] = {
	hp_warning = "こうなったら、一か八かの賭けに出るまで！",
	feeling3 = "何かしらの役に立つと思って、昨日の戦いに関する振り返り資料を作成してみました。それと最近の依頼もまとめて…うっ、なんだか眩暈が…いいえ、大したことはないですが、ちょっと体に…力が…",
