_G.pg.base.ship_skin_words[9705040] = {
	hp_warning = "冗談じゃないわ！こんなの認めないんだから！",
	feeling3 = "忠誠を誓うことにまだ悩んでいるの？ふん、有能な者が人に従いたくないのはわかっているつもりよ。ちゃんと自分の仕事をこなしなさい。ただ、私に助けが必要なときだけ力を貸すがいいわ",
