_G.pg.base.ship_skin_words[9705060] = {
	hp_warning = "余は倒れぬ……倒れぬぞ！",
	feeling3 = "いつまでも前線で戦ってはいかぬ、と？…なぜ駄目と申すか？余の守りがなく、仲間に傷付くことがあったらどうするつもりだ？お主を信じてほしい、と…？うむ…ならばお主の采配、見させてもらうぞ",
	mail = "指揮官、お主宛のメールはまとめておいた。確認を忘れぬように。仲間の期待に背くのは許されぬぞ",
	expedition = "委託が完了した。……うむ、余と共に帰還した仲間たちを出迎えようぞ",
	win_mvp = "咲いては散るは花の定め。果てゆくはお主らの定めぞ",
	home = "お主はよくやっておる。褒美は何を望む？かしこまらずに余に願い出ると良い",
	unlock = "余は長門、「重桜」の御狐である。そなたはなにゆえ余をここに呼び出した？力を欲するか？それとも余に願い事でもしたいのか？",
	touch2 = "おこがましいことをしておる自覚はあるか？",
	mission = "指揮官、任務の文書は片付いた。残りはお主がこなせ",
	vote = "",
	drop_descrip = "長門型戰艦一番艦·長門<color=#92fc63>（1隻しか所持できません。2隻目を入手した場合、限界突破素材に変換されます）</color>",
	feeling4 = "いつの間にかお主が側にいることに慣れてしまっておる。余を恐れず、余に畏まることもないお主を面白く思うが……お主に欲というものはないのか？お主さえよければ、何だって賜ってやれるのに――願い事でもしてみるか？",
	lose = "……月は満ち欠け、塞翁が馬。まだ終わってはおらぬぞ！",
	feeling1 = "……もう良い。好きにするがいい",
	skill = "嘯く御狐、天原に舞い祀ろう！",
	upgrade = "力こそ余が欲するもの、強きに越したことはない",
	propose = "うむ…お主のこの願い事は余の予想内であり、まさに自然な成り行きぞ。だがその願いの意味を本当に分かっておるのか？……もっとも、今更分からぬとは言わせぬぞ。余はすでに受け入れたし、花は短し、乙女の春宵も一瞬の如く…ここまで来てぼーっとすることはなかろう？余を…受け入れるのだぞ？",
	feeling5 = "最初は花見、その次は月見に来るよう願い出るとは……お主は謀っておるな？自らの願いと偽って、余に気を抜かせるなどと…ならその行いで手を打とう。いいか？お主の願い事を聞き届けるのはこれで最後――よく考えて申し出るのだぞ？",
	main = "指揮官、母港の桜が……本当に美しい|余を敬い、余を畏れ、皆が無事であればそれで良い|余の力は強大である。困ったことでもあれば余に頼るといい",
