_G.pg.base.ship_skin_words[9705070] = {
	hp_warning = "賽が投げられた以上…進むのみ！",
	feeling3 = "凱旋の光景は何回も夢見た。凱旋門の花道を歩み、すべての人が我が偉業を称えて――所詮はただの夢幻ね",
	mail = "メールには時効性があるわ。確認するのを忘れないで",
	expedition = "委託組が戻ってきた。兵站の大切さを胸に、共に彼女たちの凱旋を迎えに行こう",
	win_mvp = "勝利と栄光は常に私と共に",
	home = "やっぱり体は戦場のほうに馴染んでいる。次の出撃は私も同行させてもらうわ",
	unlock = "私は帝国の征服者、ジュリオ・チェザーレ。余計なおしゃべりなんて不要。つまらない些事に時間を浪費したくないわ",
	touch2 = "いいわね。征服者たる指揮官はそうでなくちゃ",
