	mission_complete = "精度が高く効率も上々。いいわね",
	battle = "征服を始めよう！",
	id = 9705070,
	gift_dislike = "",
	gift_prefer = "これはいいものだ。助かる",
	profile = "帝国の征服者、ジュリオ・チェザーレよ。来て、見て、征服して―――そしてやがて故郷へ……栄光に輝く大地へと凱旋するだろう",
	voice_key = 970507,
	headtouch = "レギオンのガレアも好きだけど…軍帽もいいわね",
	feeling2 = "指揮官は指導者として非常に優秀よ。私たちが協力すればきっと勝ち続けて、永遠の栄光を手にできるわ",
	login = "来たのね？集中して職務に掛かりなさい",
