_G.pg.base.ship_skin_words[9705080] = {
	hp_warning = "大丈夫。ただのかすり傷よ",
	feeling3 = "部下のメンタルとコンディションに気を配り、個々に応じてケアすること…この点はまだまだ指揮官くんに学ばないといけないようね",
	mail = "指揮官くん、新しいメールを持ってきたわ。ただの定期連絡だから、時間がある時にチェックしてね",
	expedition = "うん――順調な航路なくして、商売繫盛は語れないからね。指揮官くん、上出来よ",
	win_mvp = "勝つべくして勝った、というわけね。ふふふ、みんなお疲れ様～",
	home = "指揮官くん、顔に疲れが出ているわよ？仲間たちの振り返りなんて瑣末事は私に任せればいいから、先に休んでて～",
	unlock = "サルデーニャ同盟のアンドレア・ドーリアよ。指揮官くん、ここがあなたの母港なのかしら？なるほど――いいところね。好きになりそう～",
	touch2 = "ふふふ、私になら…思う存分甘えてくれていいわよ",
	mission = "指揮官くん、新しい任務が届いているわ。何か私に手伝えることはあるかしら？",
	vote = "",
	drop_descrip = "アンドレア・ドーリア級戦艦-アンドレア・ドーリア<color=#92fc63>（1隻しか所持できません。2隻目を入手した場合、限界突破素材に変換されます）</color>",
	feeling4 = "指揮官くんってストレートのホットミルクのように、温かくどこかノスタルジックね…対して私はピュアココアってところかしら。底知れなく、黒く渦巻いている…ふふふ、指揮官くん、混ぜ混ぜしたホットココアでも一杯いかが？",
	lose = "大変…怪我人はすぐ戻って手当てを受けて！この勝利は明日に預けるわ…！",
	feeling1 = "指揮官くん、最近の決断は少々不適切よ？",
	skill = "そうそう、もっと近くへ～",
	upgrade = "これはなかなか…ふふふ、なかなかいいわね",
	propose = "契りが交わされたわ。私はこの先永遠に離れず、ずっとずっとあなたの側に――まだ私の物語が気になるの？じゃあ――愛する指揮官くんに、百ある物語の一つを教えちゃおうかな♪",
	feeling5 = "私の過去についてもっと知りたい…？しかも記録に残っていない逸話とか？うーん……まだやめとこうかな。私にとって指揮官くんは特別な存在だから、この絆をもっと慎重に慎重にしたいのよね～",
	main = "…慣れ親しんだアンドレアとあまり違いがない？ふふふ、そう思ってもらっても結構よ|ホットミルクが大好きだけど、ミルクの入ってないピュアココアも悪くないわね…うん。指揮官くんとお喋りしてたら急に飲みたくなってきたわ。指揮官くん、一緒に飲まない？|ふぅ…長丁場でちょっと疲れちゃった。指揮官くん、一緒に息抜きでもしない？",
	touch = "落ち込んでいる時…普通に温かいハグをすれば指揮官くんを癒せると思うわ",
	voice_key_2 = -1,
	mission_complete = "指揮官くん、任務が無事完了したわ。…あ、ごめんなさいね。つい指揮官くんをよしよししたくなって…本当にお疲れ様♪",
	battle = "勝利を目指して、前進！",
