_G.pg.base.ship_skin_words[9705090] = {
	hp_warning = "かすり傷だよ！指揮官はあたしが守る！",
	feeling3 = "買い物か…？いいけど、警戒は怠らないからな。あんたのためだ",
	mail = "あんた宛の手紙だ。いつも通り、怪しいものがないか確認させてもらったよ",
	expedition = "みんな無事に戻ってきたようだね。一緒に出迎えに行こう。あたしもみんなに怪我がないか確認をしないとな",
	win_mvp = "勝ったけど、まだまだ改善の余地はあるよ",
	home = "疲れたかい？怪我してないか確認させて……うん、大丈夫そうで何よりだ。水と応急キットがあるから、必要ならいつでも声をかけな",
	unlock = "よっ、少年。なかなかしっかりしてるように見えるが、この母港がいつまでも穏やかなままとは限らないぞ――こっからはあたし、このネバダについてきな！何があっても庇ってやるからよ！",
	touch2 = "……っ！ふぅ…あんたかい。次は声をかけてくれ。ここは「重点防御」なんだから",
	mission = "指揮官、まだ任務が残ってるな。あたしも手伝わせてもらうよ。アクシデントへの備えはちゃんとできてるから",
	vote = "",
	drop_descrip = "よっ、少年。なかなかしっかりしてるように見えるが、この母港がいつまでも穏やかなままとは限らないぞ――こっからはあたし、このネバダについてきな！何があっても庇ってやるからよ！",
	feeling4 = "時々ちょっと強引すぎないかって思う時もあるけど…でもあんたが無事でいるのを見ると、これでよかった気がするんだ",
	lose = "ちっ、指揮官、早く退避して！ここはあたしに任せな！",
	feeling1 = "あんたなら気持ちを分かってくれると思ってた。結局あたしは甘かったな",
	skill = "一万年早いよ！",
	upgrade = "ふん、いい感じ！この力であんたのことを守ってやるよ",
	propose = "覚悟は決まったかい？その行動が意味するのは、あんたがこんなあたしを受け入れたってこと……いい目つきだ。もう立派な男になったね。じゃああたしの一生のお願いを聞いてくれないかい？…これからもずっと、あたしにあんたを守らせてくれ",
	feeling5 = "やっと分かったよ。あたしが一番用心しているのは外の脅威ではなく、あんたを失う可能性なんだ…だからずっと守り続ける。あんたがあたしを完全に信じてくれるまでな",
