_G.pg.base.ship_skin_words[9707070] = {
	hp_warning = "この痛み…もう慣れています",
	feeling3 = "今日、ロイヤルの寮を通りかかった時、アーク・ロイヤルさんと駆逐艦たちが遠くに見えて……何と言いますか、相変わらずですね",
