_G.pg.base.ship_skin_words[9707080] = {
	hp_warning = "……観測を続ける……最後の瞬間まで……",
	feeling3 = "……この世界には私なんかよりも価値のある観測対象が数多くあるのに、あなたの視線はいつも私に向いていて……その気持ち…分かるわ",
	mail = "……メールにはとても重要な情報が記されているわ。必ず目を通してあげて",
