	touch2 = "……ふぅ…私、分かって……分かっているわ……",
	mission = "……新しい任務が来たわ。指揮官さまにとって、これらはとても重要なことよね",
	vote = "",
	drop_descrip = "ヨークタウン級航空母艦・ヨークタウン<color=#92fc63>（1隻しか所持できません。2隻目を入手した場合、限界突破素材に変換されます）</color>",
	feeling4 = "……指揮官さま、もっとあなたの笑顔を見せて。例え観測に何の意味も成さないとしても、それでも私は……満たされるから",
	lose = "………是即ち、敗北なり",
