_G.pg.base.ship_skin_words[899030] = {
	hp_warning = "まだ焦る時ではありませんね～",
	feeling3 = "物語の中の賢者はヒトの運命をも言い当てます。そんな力を持っていなくても、あなたの物語を間近で見届けてきた私は、あなたが偉大な英雄になれると信じていますよ",
	mail = "新しいメールが来ましたね",
